describe('ShoppingCart', () => {
  let cart;

  beforeEach(() => {
    cart = new ShoppingCart();
  });

  describe('constructor', () => {
    it('starts empty with no discount', () => {
      assert.deepEqual(cart.items, []);
      assert.equal(cart.discount, 0);
      assert.equal(cart.getItemCount(), 0);
    });
  });

  describe('addItem', () => {
    it('adds a new item', () => {
      cart.addItem('apple', 1.5, 2);
      assert.deepEqual(cart.items, [{ name: 'apple', price: 1.5, quantity: 2 }]);
    });

    it('adds multiple distinct items', () => {
      cart.addItem('apple', 1, 1);
      cart.addItem('banana', 2, 3);
      assert.equal(cart.getItemCount(), 2);
    });

    it('merges quantities when the same item is added again', () => {
      cart.addItem('apple', 1, 2);
      cart.addItem('apple', 1, 3);
      assert.equal(cart.getItemCount(), 1);
      assert.equal(cart.items[0].quantity, 5);
    });

    it('allows a zero price (free item)', () => {
      cart.addItem('sticker', 0, 1);
      assert.equal(cart.getItemCount(), 1);
      assert.equal(cart.getTotal(), 0);
    });

    it('rejects a zero quantity', () => {
      assert.throws(() => cart.addItem('apple', 1, 0), RangeError);
      assert.equal(cart.getItemCount(), 0);
    });

    it('rejects a fractional quantity', () => {
      assert.throws(() => cart.addItem('apple', 1, 1.5), RangeError);
      assert.equal(cart.getItemCount(), 0);
    });

    it('rejects non-numeric price and quantity', () => {
      assert.throws(() => cart.addItem('apple', '1', 1), RangeError);
      assert.throws(() => cart.addItem('apple', 1, '2'), RangeError);
      assert.throws(() => cart.addItem('apple', undefined, 1), RangeError);
      assert.throws(() => cart.addItem('apple', 1, undefined), RangeError);
      assert.equal(cart.getItemCount(), 0);
    });

    it('rejects NaN and Infinity', () => {
      assert.throws(() => cart.addItem('apple', NaN, 1), RangeError);
      assert.throws(() => cart.addItem('apple', Infinity, 1), RangeError);
      assert.throws(() => cart.addItem('apple', 1, NaN), RangeError);
      assert.throws(() => cart.addItem('apple', 1, Infinity), RangeError);
      assert.equal(cart.getItemCount(), 0);
    });

    it('does not concatenate a string quantity onto an existing item', () => {
      cart.addItem('apple', 1, 2);
      assert.throws(() => cart.addItem('apple', 1, '3'), RangeError);
      assert.equal(cart.items[0].quantity, 2);
    });
  });

  describe('removeItem', () => {
    it('removes an existing item and returns true', () => {
      cart.addItem('apple', 1, 1);
      assert.equal(cart.removeItem('apple'), true);
      assert.equal(cart.getItemCount(), 0);
    });

    it('removes only the named item from a cart with several', () => {
      cart.addItem('apple', 1, 1);
      cart.addItem('banana', 2, 1);
      cart.addItem('cherry', 3, 1);
      cart.removeItem('banana');
      assert.deepEqual(
        cart.items.map(i => i.name),
        ['apple', 'cherry']
      );
    });

    it('returns false and leaves the cart untouched when the item is missing', () => {
      cart.addItem('apple', 1, 1);
      assert.equal(cart.removeItem('nonexistent'), false);
      assert.deepEqual(cart.items, [{ name: 'apple', price: 1, quantity: 1 }]);
    });

    it('returns false on an empty cart', () => {
      assert.equal(cart.removeItem('apple'), false);
      assert.equal(cart.getItemCount(), 0);
    });

    it('updates the total after removal', () => {
      cart.addItem('apple', 1, 2);
      cart.addItem('banana', 5, 1);
      cart.removeItem('banana');
      assert.equal(cart.getTotal(), 2);
    });
  });

  describe('getTotal', () => {
    it('returns 0 for an empty cart', () => {
      assert.equal(cart.getTotal(), 0);
    });

    it('returns price * quantity for a single item', () => {
      cart.addItem('apple', 2.5, 4);
      assert.equal(cart.getTotal(), 10);
    });

    it('sums all items', () => {
      cart.addItem('apple', 1, 2);
      cart.addItem('banana', 3, 1);
      cart.addItem('cherry', 0.5, 4);
      assert.equal(cart.getTotal(), 7);
    });

    it('handles cent prices', () => {
      cart.addItem('widget', 19.99, 3);
      assertClose(cart.getTotal(), 59.97);
    });

    it('reflects merged quantities', () => {
      cart.addItem('apple', 2, 1);
      cart.addItem('apple', 2, 2);
      assert.equal(cart.getTotal(), 6);
    });
  });

  describe('applyDiscount', () => {
    beforeEach(() => {
      cart.addItem('item', 100, 1);
    });

    it('reduces the total by the given percentage', () => {
      cart.applyDiscount(10);
      assert.equal(cart.getTotal(), 90);
    });

    it('accepts 0% (no change)', () => {
      cart.applyDiscount(0);
      assert.equal(cart.getTotal(), 100);
    });

    it('accepts 100% (free)', () => {
      cart.applyDiscount(100);
      assert.equal(cart.getTotal(), 0);
    });

    it('accepts fractional percentages', () => {
      cart.applyDiscount(12.5);
      assert.equal(cart.getTotal(), 87.5);
    });

    it('replaces a previous discount rather than stacking', () => {
      cart.applyDiscount(10);
      cart.applyDiscount(25);
      assert.equal(cart.getTotal(), 75);
    });

    it('applies to items added after the discount', () => {
      cart.applyDiscount(50);
      cart.addItem('other', 20, 1);
      assert.equal(cart.getTotal(), 60);
    });

    it('rejects non-numeric values', () => {
      assert.throws(() => cart.applyDiscount('10'), RangeError);
      assert.throws(() => cart.applyDiscount(undefined), RangeError);
      assert.throws(() => cart.applyDiscount(null), RangeError);
      assert.throws(() => cart.applyDiscount(NaN), RangeError);
      assert.equal(cart.getTotal(), 100);
    });
  });

  // Each block below targets one of the five original bugs. With the other
  // four bugs fixed, reintroducing any single bug makes its block fail.
  describe('regression tests', () => {
    describe('bug 1: addItem accepted negative price or quantity', () => {
      it('throws on a negative price and does not add the item', () => {
        assert.throws(() => cart.addItem('apple', -5, 1), RangeError);
        assert.equal(cart.getItemCount(), 0);
      });

      it('throws on a negative quantity and does not add the item', () => {
        assert.throws(() => cart.addItem('apple', 5, -1), RangeError);
        assert.equal(cart.getItemCount(), 0);
      });

      it('does not let a negative quantity reduce an existing item', () => {
        cart.addItem('apple', 5, 3);
        assert.throws(() => cart.addItem('apple', 5, -2), RangeError);
        assert.equal(cart.items[0].quantity, 3);
      });

      it('cannot produce a negative total', () => {
        cart.addItem('apple', 5, 1);
        assert.throws(() => cart.addItem('refund', -100, 1), RangeError);
        assert.equal(cart.getTotal(), 5);
      });
    });

    describe('bug 2: removeItem used = instead of !== and ignored missing items', () => {
      it('actually removes the item', () => {
        cart.addItem('apple', 1, 1);
        cart.addItem('banana', 2, 1);
        cart.removeItem('apple');
        assert.equal(cart.getItemCount(), 1);
        assert.equal(cart.items[0].name, 'banana');
      });

      it('does not rename the remaining items', () => {
        cart.addItem('apple', 1, 1);
        cart.addItem('banana', 2, 1);
        cart.removeItem('apple');
        assert.ok(cart.items.every(i => i.name !== 'apple'));
      });

      it('leaves the cart unchanged and reports false for a missing item', () => {
        cart.addItem('apple', 1, 1);
        cart.addItem('banana', 2, 1);
        assert.equal(cart.removeItem('grape'), false);
        assert.deepEqual(
          cart.items.map(i => i.name),
          ['apple', 'banana']
        );
      });
    });

    describe('bug 3: getTotal looped one past the end (<=)', () => {
      it('does not throw on an empty cart', () => {
        assert.doesNotThrow(() => cart.getTotal());
        assert.equal(cart.getTotal(), 0);
      });

      it('does not throw with items in the cart', () => {
        cart.addItem('apple', 1, 1);
        cart.addItem('banana', 2, 1);
        assert.doesNotThrow(() => cart.getTotal());
        assert.equal(cart.getTotal(), 3);
      });
    });

    describe('bug 4: discount was added to the total instead of subtracted', () => {
      it('a 20% discount on 50 yields 40, not 60', () => {
        cart.addItem('item', 50, 1);
        cart.applyDiscount(20);
        assert.equal(cart.getTotal(), 40);
      });

      it('a discounted total is never higher than the undiscounted total', () => {
        cart.addItem('item', 80, 1);
        const before = cart.getTotal();
        cart.applyDiscount(5);
        assert.ok(cart.getTotal() < before);
      });
    });

    describe('bug 5: applyDiscount accepted values outside 0-100', () => {
      beforeEach(() => {
        cart.addItem('item', 100, 1);
      });

      it('throws on a discount above 100', () => {
        assert.throws(() => cart.applyDiscount(150), RangeError);
      });

      it('throws on a negative discount', () => {
        assert.throws(() => cart.applyDiscount(-10), RangeError);
      });

      it('keeps the previous discount when an invalid one is rejected', () => {
        cart.applyDiscount(10);
        assert.throws(() => cart.applyDiscount(101), RangeError);
        assert.throws(() => cart.applyDiscount(-1), RangeError);
        assert.equal(cart.discount, 10);
        assert.equal(cart.getTotal(), 90);
      });
    });
  });

  describe('getItemCount', () => {
    it('counts distinct line items, not total quantity', () => {
      cart.addItem('apple', 1, 5);
      cart.addItem('banana', 1, 2);
      assert.equal(cart.getItemCount(), 2);
    });

    it('decreases after a removal', () => {
      cart.addItem('apple', 1, 1);
      cart.addItem('banana', 1, 1);
      cart.removeItem('apple');
      assert.equal(cart.getItemCount(), 1);
    });
  });
});

